#pragma once
#include "../Runtime/BrowserLibraryImport.h"
#include "GitRepositoryIdentityTests.h"

namespace coincide {
inline int browser_history_sqlite_tests(const std::filesystem::path& report){
    using namespace browser_library;using namespace sqlite_metadata;std::size_t checks{};const auto check=[&](bool value,const char* message){++checks;if(!value)throw std::runtime_error("check "+std::to_string(checks)+": "+message);};const auto rejects=[&](auto action,const char* message){bool rejected{};try{action();}catch(...){rejected=true;}check(rejected,message);};
    try{
        git_identity_fixture::Directory owned;API api;struct Database{API& api;sqlite3* value{};~Database(){if(value)api.close(value);}} chrome{api},firefox{api},unsupported{api};const auto history=owned.path/L"History",places=owned.path/L"places.sqlite";
        check(api.open(filename(history).c_str(),&chrome.value,SQLITE_OPEN_READWRITE|SQLITE_OPEN_CREATE,nullptr)==SQLITE_OK,"owned Chromium SQLite fixture must open through the OS reader");
        const auto sql=[&](sqlite3* db,const char* statement){if(api.exec(db,statement,nullptr,nullptr,nullptr)!=SQLITE_OK)throw std::runtime_error("Owned SQLite fixture statement failed");};
        sql(chrome.value,"PRAGMA journal_mode=WAL; PRAGMA wal_autocheckpoint=0; CREATE TABLE urls(id INTEGER PRIMARY KEY,url TEXT,title TEXT,visit_count INTEGER,last_visit_time INTEGER,hidden INTEGER DEFAULT 0); INSERT INTO urls(id,url,title,visit_count,last_visit_time) VALUES(1,'https://owned.invalid/','Owned committed history',7,13300000000000000); INSERT INTO urls(id,url,title,visit_count,last_visit_time) VALUES(2,'javascript:blocked','Blocked',1,13300000000000001); INSERT INTO urls VALUES(4,'https://hidden.invalid/','Hidden redirect must not import',1,13300000000000003,1);");const auto main_before=local_file::read(history,database_limit).digest,wal_before=local_file::read(history.wstring()+L"-wal",wal_limit).digest;
        const auto preview=Reader::preview(history);check(preview.wal&&preview.history.size()==1&&preview.history.front().visits==7&&preview.skipped==1,"actual copied WAL rows must appear while unsafe schemes are excluded");check(preview.history.front().at==13300000000000LL-11644473600000LL,"Chromium microseconds since 1601 must convert to Unix milliseconds");check(local_file::read(history,database_limit).digest==main_before&&local_file::read(history.wstring()+L"-wal",wal_limit).digest==wal_before,"SQLite preview must leave original main database and WAL bytes unchanged");Reader::verify(preview);sql(chrome.value,"INSERT INTO urls(id,url,title,visit_count,last_visit_time) VALUES(3,'https://new.invalid/','Changed after preview',1,13300000000000002);");rejects([&]{Reader::verify(preview);},"changes to a live selected WAL must invalidate its reviewed import preview");
        owned.write(L"History-journal","Owned active rollback marker");rejects([&]{Reader::preview(history);},"uncommitted rollback journals must not be mistaken for a consistent browser history snapshot");std::filesystem::remove(owned.path/L"History-journal");
        check(api.open(filename(places).c_str(),&firefox.value,SQLITE_OPEN_READWRITE|SQLITE_OPEN_CREATE,nullptr)==SQLITE_OK,"owned Firefox SQLite fixture must open");sql(firefox.value,"CREATE TABLE moz_places(id INTEGER PRIMARY KEY,url TEXT,title TEXT,visit_count INTEGER,last_visit_date INTEGER,hidden INTEGER DEFAULT 0); CREATE TABLE moz_bookmarks(id INTEGER PRIMARY KEY,type INTEGER,fk INTEGER,parent INTEGER,title TEXT,dateAdded INTEGER); INSERT INTO moz_places(id,url,title,visit_count,last_visit_date) VALUES(1,'https://firefox.invalid/','Owned Firefox history',4,1700000000000000); INSERT INTO moz_places VALUES(2,'https://hidden-firefox.invalid/','Hidden',4,1700000000000001,1); INSERT INTO moz_places VALUES(3,'https://unvisited.invalid/','Unvisited',0,0,0); INSERT INTO moz_bookmarks VALUES(10,2,NULL,0,'Toolbar',0); INSERT INTO moz_bookmarks VALUES(11,1,1,10,'Owned bookmark',1);");const auto firefox_before=local_file::read(places,database_limit).digest;const auto ff=Importer::preview(places);check(ff.history.size()==1&&ff.bookmarks.size()==1&&ff.bookmarks.front().folder.find("Toolbar")!=std::string::npos,"actual Firefox history and bookmark joins must use fixed supported metadata tables");check(ff.history.front().at==1700000000000LL&&local_file::read(places,database_limit).digest==firefox_before,"Firefox timestamps must convert without writing the original database");Importer::verify(ff);
        const auto private_db=owned.path/L"history.sqlite";check(api.open(filename(private_db).c_str(),&unsupported.value,SQLITE_OPEN_READWRITE|SQLITE_OPEN_CREATE,nullptr)==SQLITE_OK,"owned unsupported schema fixture must open");sql(unsupported.value,"CREATE TABLE logins(username TEXT,password TEXT); INSERT INTO logins VALUES('SYNTHETIC-NEVER-READ','SYNTHETIC-NEVER-READ');");rejects([&]{Reader::preview(private_db);},"unsupported SQLite schemas must refuse import without querying credential fields");rejects([&]{Reader::preview(owned.path/L"Login Data");},"credential database filenames must not be accepted as browser history sources");
        std::ofstream output(report);output<<"PASS: "<<checks<<" Windows system-SQLite browser metadata checks; owned main/WAL fixtures only, no owner browsers/auth/network\n";return output?0:2;
    }catch(const std::exception& error){std::ofstream(report)<<"FAIL: "<<error.what()<<'\n';return 1;}catch(const winrt::hresult_error& error){std::ofstream(report)<<"FAIL: Windows SQLite metadata API error "<<static_cast<unsigned>(error.code())<<'\n';return 1;}
}
}
